# >>> STATIC
_static_io_recordVideo_mask() {
    cat <<-'ARGCEOF'
	ignored	The mask is ignored and the unmasked framebuffer is saved
	alpha	Not supported, but retained for compatibility; the mask is rendered black
	black	The mask is rendered black
ARGCEOF
}

_static_io_screenshot_mask() {
    cat <<-'ARGCEOF'
	ignored	The mask is ignored and the unmasked framebuffer is saved
	alpha	The mask is used as premultiplied alpha
	black	The mask is rendered black
ARGCEOF
}

_static_logverbose_action() {
    cat <<-'ARGCEOF'
	enable	Enables verbose logging
	disable	Disables verbose logging
ARGCEOF
}

_static_privacy_action() {
    cat <<-'ARGCEOF'
	grant	Grant access without prompting
	revoke	Revoke access, denying all use of the service
	reset	Reset access, prompting on next use
ARGCEOF
}

_static_privacy_service() {
    cat <<-'ARGCEOF'
	all	Apply the action to all services
	calendar	Allow access to calendar
	contacts-limited	Allow access to basic contact info
	contacts	Allow access to full contact details
	location	Allow access to location services when app is in use
	location-always	Allow access to location services at all times
	photos-add	Allow adding photos to the photo library
	photos	Allow full access to the photo library
	media-library	Allow access to the media library
	microphone	Allow access to audio input
	motion	Allow access to motion and fitness data
	reminders	Allow access to reminders
	siri	Allow use of the app with Siri
ARGCEOF
}

_static_ui_appearance_style() {
    cat <<-'ARGCEOF'
	light	The Light appearance style
	dark	The Dark appearance style
ARGCEOF
}

_static_ui_increase_contrast_state() {
    cat <<-'ARGCEOF'
	enabled	Increase Contrast is enabled
	disabled	Increase Contrast is disabled
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_app_bundle_identifier() {
    local device=${argc_device:-}
    [[ -n $device ]] || return 0
    simctl listapps "$device" 2>/dev/null | plutil -convert json -o - - 2>/dev/null | jq -b -r 'keys[]'
}

_choice_arch() {
    printf '%s\n' arm64 x86_64
}

_choice_container() {
    printf '%s\t%s\n' app 'The .app bundle' data "The application's data container" groups 'The App Group containers'
}

_choice_device() {
    printf '%s\n' booted
    _helper_devices
}

_choice_device_delete() {
    _helper_devices
    printf '%s\t%s\n' unavailable 'Device unavailable in the current Xcode SDK' all 'All devices'
}

_choice_devicetype() {
    simctl list devicetypes --json 2>/dev/null | jq -b -r '.devicetypes[] | "\(.name)\t\(.identifier)", .identifier'
}

_choice_display() {
    printf '%s\n' internal external
}

_choice_pair() {
    simctl list pairs --json 2>/dev/null | jq -b -r '.pairs | keys[]'
}

_choice_pbsync_endpoint() {
    printf '%s\n' host
    _choice_device
}

_choice_runtime() {
    simctl list runtimes --json 2>/dev/null | jq -b -r '.runtimes[] | "\(.name)\t\(.identifier)", .identifier'
}

_choice_scenario() {
    local device=${argc_device:-}
    [[ -n $device ]] || return 0
    simctl location "$device" list 2>/dev/null | grep -v '^No devices'
}

_helper_devices() {
    simctl list devices --json 2>/dev/null | jq -b -r '.devices[] | .[] | "\(.name)\t\(.state)", .udid'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
